import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import App from './App';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </React.StrictMode>
);

import { Routes, Route, Navigate, NavLink } from 'react-router-dom';
import { Navbar, Nav, Container } from 'react-bootstrap';
import SneakerCollection from './pages/SneakerCollection';
import SneakerManagement from './pages/SneakerManagement';
import SneakerForm from './pages/SneakerForm';
import { ROLL } from './constants';

export default function App() {
  return (
    <>
      <Navbar bg="dark" variant="dark" expand="md">
        <Container>
          <Navbar.Brand>Sneaker Store</Navbar.Brand>
          <Nav className="me-auto">
            <Nav.Link as={NavLink} to={`/${ROLL}/sneaker-collection`}>Sneaker Collection</Nav.Link>
            <Nav.Link as={NavLink} to={`/${ROLL}/sneaker-management`}>Sneaker Management</Nav.Link>
          </Nav>
        </Container>
      </Navbar>

      <Container className="my-4">
        <Routes>
          <Route path="/" element={<Navigate to={`/${ROLL}/sneaker-collection`} replace />} />
          <Route path={`/${ROLL}/sneaker-collection`} element={<SneakerCollection />} />
          <Route path={`/${ROLL}/sneaker-management`} element={<SneakerManagement />} />
          <Route path={`/${ROLL}/add-sneaker`} element={<SneakerForm />} />
          <Route path={`/${ROLL}/edit-sneaker/:id`} element={<SneakerForm />} />
        </Routes>
      </Container>
    </>
  );
}

import axios from 'axios';

// Read the API URL from .env — never hard-code it (0 points otherwise).
// CRA: REACT_APP_API_URL + process.env  ·  Vite: VITE_API_URL + import.meta.env
const API_URL = process.env.REACT_APP_API_URL;

export const getSneakers = () => axios.get(API_URL).then((res) => res.data);
export const getSneaker = (id) => axios.get(`${API_URL}/${id}`).then((res) => res.data);
export const createSneaker = (data) => axios.post(API_URL, data).then((res) => res.data);
export const updateSneaker = (id, data) => axios.put(`${API_URL}/${id}`, data).then((res) => res.data);
export const deleteSneaker = (id) => axios.delete(`${API_URL}/${id}`);

export const CATEGORIES = ['Running', 'Basketball', 'Lifestyle', 'Skateboarding', 'Training'];

// retailPriceK is in THOUSANDS of VND: 189 -> "189,000 VND"
export const formatVnd = (priceK) => `${(Number(priceK) * 1000).toLocaleString('en-US')} VND`;

// Task 2: descending alphabetical order by sneakerName
export const byNameDesc = (a, b) => b.sneakerName.localeCompare(a.sneakerName);

// Task 3: ascending by id. mockapi returns id as a STRING ("1", "2", ..., "10"),
// so compare as numbers — a string sort would put "10" before "2".
export const byIdAsc = (a, b) => Number(a.id) - Number(b.id);

const isValidUrl = (value) => {
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
};

// Returns { field: message } — an empty object means the form is valid.
export function validateSneaker(form) {
  const errors = {};
  const name = form.sneakerName.trim();
  const brand = form.brandName.trim();
  const url = form.sneakerImageUrl.trim();
  const price = String(form.retailPriceK).trim();

  if (!name) errors.sneakerName = 'Sneaker name is required.';
  else if (name.length < 2) errors.sneakerName = 'Sneaker name must contain at least 2 characters.';

  if (!brand) errors.brandName = 'Brand name is required.';
  else if (brand.split(/\s+/).filter(Boolean).length < 2) errors.brandName = 'Brand name must consist of at least 2 words.';

  if (!form.sneakerCategory) errors.sneakerCategory = 'Please select a sneaker category.';
  else if (!CATEGORIES.includes(form.sneakerCategory)) errors.sneakerCategory = 'Invalid sneaker category.';

  if (!url) errors.sneakerImageUrl = 'Image URL is required.';
  else if (!isValidUrl(url)) errors.sneakerImageUrl = 'Image URL must be a valid URL.';

  if (!price) errors.retailPriceK = 'Retail price is required.';
  else if (!/^[1-9]\d{0,2}$/.test(price)) errors.retailPriceK = 'Retail price must be a positive integer of at most 3 digits.';

  return errors;
}

import { useEffect, useState } from 'react';
import { Row, Col, Card, Badge, Spinner, Alert } from 'react-bootstrap';
import { getSneakers } from '../api';
import { formatVnd, byNameDesc } from '../utils';

export default function SneakerCollection() {
  const [sneakers, setSneakers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    getSneakers()
      .then((data) => setSneakers([...data].sort(byNameDesc))) // Z -> A by sneakerName
      .catch(() => setError('Cannot load the sneaker list.'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <Spinner animation="border" />;
  if (error) return <Alert variant="danger">{error}</Alert>;

  return (
    <>
      <h2 className="mb-4">Sneaker Collection</h2>
      <Row xs={1} sm={2} md={3} lg={4} className="g-4">
        {sneakers.map((s) => (
          <Col key={s.id}>
            <Card className="h-100 shadow-sm sneaker-card">
              <Card.Img variant="top" className="sneaker-img" src={s.sneakerImageUrl} alt={s.sneakerName} />
              <Card.Body>
                <Card.Title className="sneaker-name">{s.sneakerName}</Card.Title>
                <Card.Text className="mb-1 sneaker-brand">Brand: {s.brandName}</Card.Text>
                <Card.Text className="mb-1 sneaker-category">Category: {s.sneakerCategory}</Card.Text>
                <Card.Text className="mb-2 sneaker-price">Price: {formatVnd(s.retailPriceK)}</Card.Text>
                {s.isLimitedEdition && <Badge bg="danger" className="limited-badge">Limited Edition</Badge>}
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Table, Button, Alert } from 'react-bootstrap';
import { getSneakers, deleteSneaker } from '../api';
import { byIdAsc } from '../utils';
import { ROLL } from '../constants';

export default function SneakerManagement() {
  const [sneakers, setSneakers] = useState([]);
  const [message, setMessage] = useState('');

  const loadSneakers = () =>
    getSneakers().then((data) => setSneakers([...data].sort(byIdAsc))); // 1, 2, ..., 10

  useEffect(() => {
    loadSneakers();
  }, []);

  const handleDelete = async (sneaker) => {
    // 1) confirm BEFORE removing
    if (!window.confirm(`Are you sure you want to delete "${sneaker.sneakerName}"?`)) return;
    await deleteSneaker(sneaker.id);
    // 2) notify the user, 3) reload the list
    setMessage(`Sneaker "${sneaker.sneakerName}" has been deleted successfully.`);
    loadSneakers();
  };

  return (
    <>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h2>Sneaker Management</h2>
        <Button as={Link} id="add-sneaker" to={`/${ROLL}/add-sneaker`} variant="primary">Add Sneaker</Button>
      </div>
      {message && <Alert className="success-msg" variant="success" dismissible onClose={() => setMessage('')}>{message}</Alert>}
      <Table id="sneaker-table" striped bordered hover responsive>
        <thead>
          <tr>
            <th>ID</th>
            <th>Sneaker Name</th>
            <th>Brand Name</th>
            <th>Category</th>
            <th>Image</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {sneakers.map((s) => (
            <tr key={s.id} id={`sneaker-row-${s.id}`} className="sneaker-row">
              <td className="sneaker-id">{s.id}</td>
              <td className="sneaker-name">{s.sneakerName}</td>
              <td>{s.brandName}</td>
              <td>{s.sneakerCategory}</td>
              <td>
                <img className="sneaker-thumb" src={s.sneakerImageUrl} alt={s.sneakerName} width={70} height={70} style={{ objectFit: 'cover' }} />
              </td>
              <td>
                <Link to={`/${ROLL}/edit-sneaker/${s.id}`} className="btn btn-sm btn-warning me-2 edit-link">Edit</Link>
                <Button size="sm" variant="danger" className="delete-btn" onClick={() => handleDelete(s)}>Delete</Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
    </>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Form, Button, Card } from 'react-bootstrap';
import { getSneaker, createSneaker, updateSneaker } from '../api';
import { CATEGORIES, validateSneaker } from '../utils';
import { ROLL } from '../constants';

const EMPTY = {
  sneakerName: '',
  brandName: '',
  sneakerCategory: '', // empty by default: the user has to pick one
  sneakerImageUrl: '',
  retailPriceK: '',
  isLimitedEdition: false, // switch, default false
};

// One component for both /add-sneaker and /edit-sneaker/:id
export default function SneakerForm() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const navigate = useNavigate();
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (!isEdit) {
      setForm(EMPTY);
      return;
    }
    // Pre-fill the edit form with the selected sneaker's current data
    getSneaker(id).then((s) =>
      setForm({
        sneakerName: s.sneakerName,
        brandName: s.brandName,
        sneakerCategory: s.sneakerCategory,
        sneakerImageUrl: s.sneakerImageUrl,
        retailPriceK: String(s.retailPriceK),
        isLimitedEdition: Boolean(s.isLimitedEdition),
      })
    );
  }, [id, isEdit]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm({ ...form, [name]: type === 'checkbox' ? checked : value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validateSneaker(form); // same rules for Add and Edit
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    const payload = {
      sneakerName: form.sneakerName.trim(),
      brandName: form.brandName.trim(),
      sneakerCategory: form.sneakerCategory,
      sneakerImageUrl: form.sneakerImageUrl.trim(),
      retailPriceK: Number(form.retailPriceK), // store a Number, as in the schema
      isLimitedEdition: form.isLimitedEdition, // store a Boolean
    };

    if (isEdit) {
      await updateSneaker(id, payload); // PUT /:id
      alert('Sneaker updated successfully!');
    } else {
      await createSneaker(payload); // POST
      alert('Sneaker added successfully!');
    }
    navigate(`/${ROLL}/sneaker-management`); // the table re-fetches and shows the new data
  };

  return (
    <Card className="mx-auto" style={{ maxWidth: 600 }}>
      <Card.Body>
        <Card.Title className="mb-3 form-title">{isEdit ? 'Edit Sneaker' : 'Add Sneaker'}</Card.Title>
        <Form noValidate onSubmit={handleSubmit}>
          <Form.Group className="mb-3">
            <Form.Label>Sneaker Name</Form.Label>
            <Form.Control id="sneakerName" name="sneakerName" value={form.sneakerName} onChange={handleChange} isInvalid={!!errors.sneakerName} />
            <Form.Control.Feedback type="invalid">{errors.sneakerName}</Form.Control.Feedback>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Brand Name</Form.Label>
            <Form.Control id="brandName" name="brandName" value={form.brandName} onChange={handleChange} isInvalid={!!errors.brandName} />
            <Form.Control.Feedback type="invalid">{errors.brandName}</Form.Control.Feedback>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Sneaker Category</Form.Label>
            <Form.Select id="sneakerCategory" name="sneakerCategory" value={form.sneakerCategory} onChange={handleChange} isInvalid={!!errors.sneakerCategory}>
              <option value="">-- Select a category --</option>
              {CATEGORIES.map((c) => (
                <option key={c} value={c}>{c}</option>
              ))}
            </Form.Select>
            <Form.Control.Feedback type="invalid">{errors.sneakerCategory}</Form.Control.Feedback>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Image URL</Form.Label>
            <Form.Control id="sneakerImageUrl" name="sneakerImageUrl" value={form.sneakerImageUrl} onChange={handleChange} isInvalid={!!errors.sneakerImageUrl} />
            <Form.Control.Feedback type="invalid">{errors.sneakerImageUrl}</Form.Control.Feedback>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Retail Price (thousand VND)</Form.Label>
            <Form.Control id="retailPriceK" name="retailPriceK" value={form.retailPriceK} onChange={handleChange} isInvalid={!!errors.retailPriceK} />
            <Form.Control.Feedback type="invalid">{errors.retailPriceK}</Form.Control.Feedback>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Check
              type="switch"
              id="isLimitedEdition"
              name="isLimitedEdition"
              label="Limited Edition"
              checked={form.isLimitedEdition}
              onChange={handleChange}
            />
          </Form.Group>

          <Button id="save-sneaker" type="submit" variant="primary" className="me-2">{isEdit ? 'Update' : 'Add'}</Button>
          <Button variant="secondary" onClick={() => navigate(`/${ROLL}/sneaker-management`)}>Cancel</Button>
        </Form>
      </Card.Body>
    </Card>
  );
}
